  function emptyTaskResult(task,name,profile,start){return{task,name,profile:JSON.parse(JSON.stringify(profile)),start,success:false,completedSeconds:null,duration:0,distance:0,minClearance:0,collisions:0,turnFailures:0,pathFailures:0,reachFailures:0,doorFailures:0,transferFailures:0,issues:[],probes:[],actions:[],trace:[{time:0,...start,action:'准备任务',doors:{}}]};}
